// Package alertmanager renders an Alertmanager routing snippet for the
// alerts generated from AISLO specs. It is a starting point to merge into
// an existing configuration: receivers are placeholders without integrations.
package alertmanager

import (
	"bytes"
	"slices"
	"strconv"

	"go.yaml.in/yaml/v3"

	"github.com/abhinavcdev/sloeval/internal/ir"
)

// Header starts the generated file.
const Header = `# Code generated by sloe from AISLO specs. DO NOT EDIT.
# Merge these routes into your Alertmanager config and add integrations to
# the placeholder receivers. This file never contains credentials.
`

type config struct {
	Route        route         `yaml:"route"`
	InhibitRules []inhibitRule `yaml:"inhibit_rules"`
	Receivers    []receiver    `yaml:"receivers"`
}

type route struct {
	Receiver       string   `yaml:"receiver,omitempty"`
	Matchers       []string `yaml:"matchers,omitempty"`
	GroupBy        []string `yaml:"group_by,omitempty"`
	RepeatInterval string   `yaml:"repeat_interval,omitempty"`
	Routes         []route  `yaml:"routes,omitempty"`
}

type inhibitRule struct {
	SourceMatchers []string `yaml:"source_matchers"`
	TargetMatchers []string `yaml:"target_matchers"`
	Equal          []string `yaml:"equal"`
}

type receiver struct {
	Name string `yaml:"name"`
}

// routeKey identifies one route: a severity for one owner.
type routeKey struct {
	severity string
	label    string // "team" or "sloe_service"
	value    string
}

func matcher(k, v string) string { return k + "=" + strconv.Quote(v) }

// Routes renders the routing snippet for all specs. Alerts are routed by
// severity and owner: the team label if the alert has one, otherwise the
// service.
func Routes(specs []*ir.Spec) ([]byte, error) {
	keys := map[routeKey]bool{}
	for _, s := range specs {
		for _, slo := range s.SLOs {
			for _, a := range slo.Alerts {
				k := routeKey{severity: a.Severity, label: ir.LabelService, value: slo.Service}
				if team, ok := a.Labels["team"]; ok {
					k.label, k.value = "team", team
				} else if team, ok := slo.Labels["team"]; ok {
					k.label, k.value = "team", team
				}
				keys[k] = true
			}
		}
	}
	sorted := make([]routeKey, 0, len(keys))
	for k := range keys {
		sorted = append(sorted, k)
	}
	slices.SortFunc(sorted, func(a, b routeKey) int {
		if a.value != b.value {
			return compare(a.value, b.value)
		}
		if a.label != b.label {
			return compare(a.label, b.label)
		}
		return compare(a.severity, b.severity) // page before ticket
	})

	var cfg config
	seen := map[string]bool{}
	for _, k := range sorted {
		name := k.value + "-" + k.severity
		r := route{
			Receiver: name,
			Matchers: []string{matcher(ir.LabelSeverity, k.severity), matcher(k.label, k.value)},
			GroupBy:  []string{"alertname", ir.LabelID},
		}
		if k.severity == ir.SeverityTicket {
			r.RepeatInterval = "12h"
		}
		cfg.Route.Routes = append(cfg.Route.Routes, r)
		if !seen[name] {
			seen[name] = true
			cfg.Receivers = append(cfg.Receivers, receiver{Name: name})
		}
	}
	cfg.InhibitRules = []inhibitRule{{
		SourceMatchers: []string{matcher(ir.LabelSeverity, ir.SeverityPage)},
		TargetMatchers: []string{matcher(ir.LabelSeverity, ir.SeverityTicket)},
		Equal:          []string{ir.LabelID},
	}}
	if cfg.Receivers == nil {
		cfg.Receivers = []receiver{}
	}

	var buf bytes.Buffer
	buf.WriteString(Header)
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(cfg); err != nil {
		return nil, err
	}
	if err := enc.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func compare(a, b string) int {
	switch {
	case a < b:
		return -1
	case a > b:
		return 1
	}
	return 0
}
